    }

    totalCost = 0.0;
    for ing in ingredients {
        totalCost = totalCost + ing.cost;
    }

    return
        <div class="column">
            <h2>Meal Shopping List</h2>
            <div class="input-row">
                <input
                    class="input"
                    value={mealText}
                    onChange={lambda (e: ChangeEvent) { mealText = e.target.value; }}
                    onKeyPress={handleKeyPress}
