                <button
                    class="btn-generate"
                    onClick={lambda { generateList(); }}
                    disabled={generating}
                >
                    {("Generating..." if generating else "Generate")}
                </button>
            </div>
            {(<div class="generating-msg">Generating with AI...</div>)
                if generating
                else (
