                    <input
                        type="password"
                        value={confirmPassword}
                        onChange={lambda (e: ChangeEvent) { confirmPassword = e.target.value; }}
                        placeholder="Confirm Password"
                        style={{"width": "100%", "padding": "0.75rem", "border": "1px solid #ddd", "borderRadius": "4px"}}
                    />
